SELECT id, full_name, email, job_title, salary, level, SUM(salary) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary, LAST_VALUE(level, TRUE) OVER (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_level, NTILE(10) OVER (PARTITION BY level ORDER BY salary DESC, id) AS salary_bucket FROM employees;
